import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String str = scanner.nextLine();
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < str.length()) {
            if (i + 1 < str.length() && str.charAt(i) == 'a' && str.charAt(i + 1) == 't') {
                out.append('@');
                i += 2;
            } else if (i + 2 < str.length() && str.charAt(i) == 'd' && str.charAt(i + 1) == 'o' && str.charAt(i + 2) == 't') {
                out.append('.');
                i += 3;
            } else {
                out.append(str.charAt(i));
                i++;
            }
        }

        String outStr = out.toString();

        if (outStr.startsWith("@")) {
            System.out.print("at");
        } else if (outStr.startsWith(".")) {
            System.out.print("dot");
        } else {
            System.out.print(outStr.charAt(0));
        }

        boolean firstAt = true;
        for (int j = 1; j < outStr.length(); j++) {
            char c = outStr.charAt(j);
            if (c == '@') {
                if (firstAt && j != outStr.length() - 1) {
                    System.out.print("@");
                    firstAt = false;
                } else {
                    System.out.print("at");
                }
            } else if (c == '.') {
                if (j != outStr.length() - 1) {
                    System.out.print(".");
                } else {
                    System.out.print("dot");
                }
            } else {
                System.out.print(c);
            }
        }
        System.out.println();
        scanner.close();
    }
}
